// import = bring in code from another file or package
// useState = a value the component remembers; calling its setter redraws the component
import { useState } from 'react';
// import = bring in code from another file or package
import { Button } from '@/components/ui/Button';
// import = bring in code from another file or package
import { Input } from '@/components/ui/Input';
// import = bring in code from another file or package
// useGetCategoriesQuery = generated by RTK Query from the endpoint: gives { data, isLoading, isFetching, error } and caches it
import { useGetCategoriesQuery } from './productsApi';

// The product's own fields (not variants). Used for both "new" and "edit".
// `extra` lets the "new" page put the variants editor inside the same form.
// export = other files can import this
// function Name() = a React component (capital letter): returns what to show (JSX)
// { a, b } = destructuring: take properties a and b out of an object
// onSubmit = runs when the form is sent (Enter or submit button)
export function ProductForm({ product, submitLabel, saving, onSubmit, extra }) {
  // const = a name for a value that is never reassigned
  // { a, b } = destructuring: take properties a and b out of an object
  // x = value (in parameters) = the default used when x is not given
  // useGetCategoriesQuery = generated by RTK Query from the endpoint: gives { data, isLoading, isFetching, error } and caches it
  const { data: categories = [] } = useGetCategoriesQuery();
  // const = a name for a value that is never reassigned
  // [a, b] = destructuring: take the first and second items of an array
  // useState = a value the component remembers; calling its setter redraws the component
  const [form, setForm] = useState({
    // ?. = optional chaining: stop (undefined) instead of crashing if the left side is null/undefined
    // a ?? b = a, unless a is null/undefined, then b
    name: product?.name ?? '',
    // ?. = optional chaining: stop (undefined) instead of crashing if the left side is null/undefined
    // a ?? b = a, unless a is null/undefined, then b
    brand: product?.brand ?? '',
    // ?. = optional chaining: stop (undefined) instead of crashing if the left side is null/undefined
    // a ?? b = a, unless a is null/undefined, then b
    categoryId: product?.categoryId ?? '',
    // ?. = optional chaining: stop (undefined) instead of crashing if the left side is null/undefined
    // a ?? b = a, unless a is null/undefined, then b
    description: product?.description ?? '',
    // ?.() = call only if the function exists
    // ?. = optional chaining: stop (undefined) instead of crashing if the left side is null/undefined
    // .join = turn an array into one string with a separator
    // a ?? b = a, unless a is null/undefined, then b
    images: product?.images.join('\n') ?? '',
    // ?. = optional chaining: stop (undefined) instead of crashing if the left side is null/undefined
    // a ?? b = a, unless a is null/undefined, then b
    isActive: product?.isActive ?? true,
  });
  // const = a name for a value that is never reassigned
  // => = an arrow function (a short function)
  // ...x = spread: copy all items/properties of x into here
  const set = (patch) => setForm((f) => ({ ...f, ...patch }));
  // const = a name for a value that is never reassigned
  const imageList = form.images
    // .split = cut a string into an array
    .split('\n')
    // .map = make a new array by transforming each item (in JSX: one element per item)
    // => = an arrow function (a short function)
    // .trim = remove spaces at both ends
    .map((s) => s.trim())
    // .filter = keep only the items that pass a test
    .filter(Boolean);

  // const = a name for a value that is never reassigned
  // => = an arrow function (a short function)
  const submit = (e) => {
    // preventDefault = stop the browser's default action (form submit reload, link follow)
    e.preventDefault();
    // onSubmit = runs when the form is sent (Enter or submit button)
    onSubmit({
      name: form.name,
      // .trim = remove spaces at both ends
      // a || b = OR: a if it is truthy, else b
      brand: form.brand.trim() || null,
      categoryId: form.categoryId,
      description: form.description,
      images: imageList,
      isActive: form.isActive,
    });
  };

  // return = give this value back and stop the function here
  return (
    // <form> = groups inputs; Enter or a submit button sends it (onSubmit)
    // onSubmit = runs when the form is sent (Enter or submit button)
    // { } in JSX = run JavaScript here and show its result
    // className = CSS classes (Tailwind) for this element (class is a JS keyword)
    <form onSubmit={submit} className="space-y-5">
      {/* className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
      <div className="space-y-4 rounded-xl border border-slate-200 bg-white p-5">
        {/* className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
        <h2 className="font-semibold">Details</h2>
        {/* className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
        <div className="grid gap-4 md:grid-cols-2">
          {/* required = the browser won't submit the form while this is empty
             { } in JSX = run JavaScript here and show its result
             onChange = runs on every change of an input
             => = an arrow function (a short function) */}
          <Input label="Name" name="name" required value={form.name} onChange={(e) => set({ name: e.target.value })} />
          <Input
            label="Brand"
            name="brand"
            // { } in JSX = run JavaScript here and show its result
            value={form.brand}
            // onChange = runs on every change of an input
            // { } in JSX = run JavaScript here and show its result
            // => = an arrow function (a short function)
            onChange={(e) => set({ brand: e.target.value })}
            // placeholder = grey hint text inside an empty input
            placeholder="Optional"
          />
        </div>
        {/* <label> = the name of an input; clicking it focuses the input
           className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
        <label className="block">
          {/* className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
          <span className="mb-1.5 block text-sm font-medium text-slate-700">Category</span>
          {/* <select> = a dropdown list */}
          <select
            // required = the browser won't submit the form while this is empty
            required
            // { } in JSX = run JavaScript here and show its result
            value={form.categoryId}
            // onChange = runs on every change of an input
            // { } in JSX = run JavaScript here and show its result
            // => = an arrow function (a short function)
            onChange={(e) => set({ categoryId: e.target.value })}
            // className = CSS classes (Tailwind) for this element (class is a JS keyword)
            className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"
          >
            {/* disabled = can't be clicked or typed in */}
            <option value="" disabled>
              Choose a category
            </option>
            {/* { } in JSX = run JavaScript here and show its result
               .map = make a new array by transforming each item (in JSX: one element per item)
               => = an arrow function (a short function) */}
            {categories.map((c) => (
              // key = a stable id for list items so React can track them between redraws
              // { } in JSX = run JavaScript here and show its result
              <option key={c.id} value={c.id}>
                {/* { } in JSX = run JavaScript here and show its result */}
                {c.name}
              </option>
            ))}
          </select>
        </label>
        {/* <label> = the name of an input; clicking it focuses the input
           className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
        <label className="block">
          {/* className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
          <span className="mb-1.5 block text-sm font-medium text-slate-700">Description</span>
          <textarea
            // required = the browser won't submit the form while this is empty
            required
            // { } in JSX = run JavaScript here and show its result
            rows={4}
            // { } in JSX = run JavaScript here and show its result
            value={form.description}
            // onChange = runs on every change of an input
            // { } in JSX = run JavaScript here and show its result
            // => = an arrow function (a short function)
            onChange={(e) => set({ description: e.target.value })}
            // className = CSS classes (Tailwind) for this element (class is a JS keyword)
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-brand-500"
          />
        </label>
        {/* <label> = the name of an input; clicking it focuses the input
           className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
        <label className="block">
          {/* className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
          <span className="mb-1.5 block text-sm font-medium text-slate-700">
            Image URLs (one per line, the first is the main image)
          </span>
          <textarea
            // required = the browser won't submit the form while this is empty
            required
            // { } in JSX = run JavaScript here and show its result
            rows={3}
            // { } in JSX = run JavaScript here and show its result
            value={form.images}
            // onChange = runs on every change of an input
            // { } in JSX = run JavaScript here and show its result
            // => = an arrow function (a short function)
            onChange={(e) => set({ images: e.target.value })}
            // placeholder = grey hint text inside an empty input
            placeholder="https://picsum.photos/seed/my-product/800/800"
            // className = CSS classes (Tailwind) for this element (class is a JS keyword)
            className="w-full rounded-lg border border-slate-300 px-3 py-2 font-mono text-xs outline-none focus:border-brand-500"
          />
        </label>
        {/* { } in JSX = run JavaScript here and show its result
           a && b = AND; in JSX: show b only when a is true */}
        {imageList.length > 0 && (
          // className = CSS classes (Tailwind) for this element (class is a JS keyword)
          <div className="flex gap-2">
            {/* { } in JSX = run JavaScript here and show its result
               .map = make a new array by transforming each item (in JSX: one element per item)
               => = an arrow function (a short function) */}
            {imageList.map((src) => (
              // key = a stable id for list items so React can track them between redraws
              // { } in JSX = run JavaScript here and show its result
              // alt = text describing the image for screen readers (empty = decorative)
              // className = CSS classes (Tailwind) for this element (class is a JS keyword)
              <img key={src} src={src} alt="" className="size-16 rounded-lg bg-slate-100 object-cover" />
            ))}
          </div>
        )}
        {/* <label> = the name of an input; clicking it focuses the input
           className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
        <label className="flex cursor-pointer items-center gap-2 text-sm">
          {/* { } in JSX = run JavaScript here and show its result
             onChange = runs on every change of an input
             => = an arrow function (a short function) */}
          <input type="checkbox" checked={form.isActive} onChange={(e) => set({ isActive: e.target.checked })} />
          <span>
            <b>Visible in the store.</b> Untick to hide it (products are never deleted, so past orders stay intact).
          </span>
        </label>
      </div>

      {/* { } in JSX = run JavaScript here and show its result */}
      {extra}

      {/* className = CSS classes (Tailwind) for this element (class is a JS keyword) */}
      <div className="flex justify-end">
        {/* loading="lazy" = load the image only when it gets near the screen
           { } in JSX = run JavaScript here and show its result */}
        <Button type="submit" loading={saving}>
          {/* { } in JSX = run JavaScript here and show its result */}
          {submitLabel}
        </Button>
      </div>
    </form>
  );
}
